import type{ReactNode}from'react';import{F2DeepDive,f2Quiz}from'./fashionM2Core';import type{FashionM2Question,FashionM2Source,FashionM2Takeaways}from'./fashionM2Core';import{VisualView}from'./fashionVisualKit';import type{VisualSpec}from'./fashionVisualKit';import{HEALTHCARE_PRODUCTS_CHAPTER_VISUALS}from'./healthcareProductsVisualSpecs';export const HEALTHCARE_PRODUCT_SOURCES={whoReg:{title:'WHO Regulatory Systems Strengthening',href:'https://www.who.int/teams/regulation-prequalification/regulation-and-safety/rss/programme',publisher:'World Health Organization',note:'Global medical-product regulatory-system guidance; product scope and national legal requirements still vary by jurisdiction.'},whoGmp:{title:'WHO GMP and Inspection Compendium, 10th Edition',href:'https://www.who.int/publications/i/item/9789240086081',publisher:'World Health Organization (2024)',note:'Pharmaceutical and medical-product manufacturing and quality-control guidance; the applicable standard depends on product classification and jurisdiction.'},whoPv:{title:'WHO Pharmacovigilance',href:'https://www.who.int/teams/regulation-prequalification/regulation-and-safety/pharmacovigilance',publisher:'World Health Organization',note:'Lifecycle detection, assessment, understanding and prevention of medicine- and vaccine-related adverse effects; not every food or supplement follows the same reporting system.'},whoTrace:{title:'WHO Policy Paper on Traceability of Medical Products',href:'https://iris.who.int/server/api/core/bitstreams/df2cb40f-496b-441d-940d-f6aa560c1930/content',publisher:'World Health Organization',note:'Medical-product supply-chain traceability framework; technology complements rather than replaces regulation, surveillance and response.'},codexSupp:{title:'Guidelines for Vitamin and Mineral Food Supplements — CXG 55-2005',href:'https://www.fao.org/input/download/standards/10206/cxg_055e.pdf',publisher:'Codex Alimentarius Commission',note:'Applies to vitamin and mineral supplements regulated as foods; it excludes foods for special dietary uses and does not replace national law.'},fdaClaims:{title:'Dietary Supplement Labeling Guide — Claims',href:'https://www.fda.gov/food/dietary-supplements-guidance-documents-regulatory-information/dietary-supplement-labeling-guide-chapter-vi-claims',publisher:'U.S. Food and Drug Administration',note:'U.S.-specific illustration of claim substantiation and disease-claim boundaries; not a Vietnam rule or a universal global standard.'},vnPharmacy:{title:'Law on Pharmacy No. 105/2016/QH13',href:'https://vbpl.vn/TW/Pages/vbpqen-toanvan.aspx?ItemID=11099',publisher:'Vietnam National Legal Database',note:'Official English text effective 1 January 2017 covering pharmacy business, registration, quality, pharmacovigilance, advertising, trials and prices; verify current amendments and implementing rules.'},vnFoodLaw:{title:'Consolidated Food Safety Law No. 61/VBHN-VPQH',href:'https://congbao.chinhphu.vn/van-ban/van-ban-hop-nhat-so-61-vbhn-vpqh-45855.htm',publisher:'Official Gazette of Vietnam (2025)',note:'Official consolidated food-safety law issued 15 August 2025; product category, ingredient, claim, activity and current implementing rules determine applicability.'},vnDecree15:{title:'Decree No. 15/2018/ND-CP on Food Safety',href:'https://vfa.gov.vn/van-ban/nghi-dinh-so-152018nd-cp-cua-chinh-phu-quy-dinh-chi-tiet-thi-hanh-mot-so-dieu-cua-luat-an-toan-thuc-pham.html',publisher:'Vietnam Food Administration — Ministry of Health',note:'Official decree record covering declarations, certificates, import inspection, labeling, advertising, supplements and traceability; verify current amendments and category-specific duties.'},vnData:{title:'Law on Personal Data Protection No. 91/2025/QH15',href:'https://congbao.chinhphu.vn/van-ban/luat-so-91-2025-qh15-45578.htm',publisher:'Official Gazette of Vietnam',note:'Official law effective 1 January 2026; health-related and other personal-data duties depend on processing role, data, scale, purpose and current guidance.'},vnConsumer:{title:'Law on Protection of Consumer Rights No. 19/2023/QH15',href:'https://congbao.chinhphu.vn/van-ban/luat-so-19-2023-qh15-39843.htm',publisher:'Official Gazette of Vietnam',note:'Official law effective 1 July 2024; responsibilities depend on the product, service, transaction and current implementing rules.'}} satisfies Record<string,FashionM2Source>;export type HealthcareProductSourceId=keyof typeof HEALTHCARE_PRODUCT_SOURCES;export type HealthcareProductVisualKind=`healthcare-products-m${number}-${number}`;export interface HealthcareProductCardData{title:string;chapterTitle:string;readingTime:string;legacyIndex?:number;legacyIndexes?:number[];legacyCompletionIndex?:number;migrationVersion?:string;objective:string;mateIntro:string;keyInsight:string;concepts:[];narrative:Array<{label:'What it is'|'Why it is happening'|'Real-world example'|'Vietnam example'|'Business impact';text:string}>;visualKind:HealthcareProductVisualKind;visualHeading:string;visualIntro:string;imageAlt:string;statTiles:Array<{value?:string;label:string;subtitle?:string;description:string}>;statsNote:string;keyTerms:Array<{term:string;definition:string}>;recap:string[];chapterRecap:string;deepDiveTitle:string;body:ReactNode;sources:FashionM2Source[]}export type HealthcareProductStat={value?:string;label:string;subtitle?:string;description:string};export type HealthcareProductItem={title:string;dimensions:string[];insight:string;scope:string;example:string;vietnam:string;sources:HealthcareProductSourceId[];stats?:HealthcareProductStat[];intro?:string;definitions?:Record<string,string>;legacyIndex?:number;legacyIndexes?:number[];legacyCompletionIndex?:number};export type HealthcareProductLesson=[string,HealthcareProductItem[]];

