type HealthcareDetail={dimensions:string[];scope:string;insight:string;example:string;vietnam:string;intro?:string;sources?:HealthcareProductSourceId[];definitions?:Record<string,string>};
const HEALTHCARE_DETAILS:Record<string,HealthcareDetail>={
'Where Does the Industry Begin and End?':{dimensions:['Dietary supplement','Functional food','Fortified food','Medical nutrition','Consumer health','Prescription medicine','Medical device'],scope:'The curriculum covers healthcare-related consumer products and nutrition within their actual classifications. Prescription medicines, medical devices, clinical treatment and healthcare delivery are outside scope unless needed to explain a boundary.',insight:'Dietary supplement and functional food are not medicines; general nutrition is not medical nutrition; classification, evidence, claims and permitted channels differ by product and jurisdiction.',example:'A vitamin supplement, fortified food and medical-nutrition product can address related needs while following different evidence, labeling and use conditions.',vietnam:'Classify each product under current Vietnamese rules based on composition, intended use, claims, target user and activity; do not import another jurisdiction’s classification.'},
'Understanding Product Categories and Regulatory Classifications':{dimensions:['Intended use','Composition','Product classification','Nutrient content claim','Health claim','Disease claim','Target population'],scope:'Classification depends on intended use, composition, presentation, claims and jurisdiction. Nutrient content, health and disease-treatment claims have different evidence and legal implications.',insight:'Registration or notification is not clinical proof of efficacy; safety is not guaranteed benefit; a marketing statement is not scientific evidence.',example:'Evidence about an ingredient does not automatically substantiate the finished product, formulation, serving, population or claimed outcome.',vietnam:'Verify current category, market-access process, label, advertising and post-market duties from primary sources.'},
'How Are Healthcare and Nutrition Markets Measured?':{dimensions:['Supplement market','Functional food','Specialized nutrition','OTC scope','Pharmaceutical market','Manufacturer revenue','Retail sales','Patient reach'],scope:'Market estimates can include different products, channels, prescription status, geographies and revenue bases. Incompatible supplement, nutrition, OTC and pharmaceutical estimates must not be added.',insight:'Market revenue is not manufacturer profit, product registration is not use, consumer awareness is not efficacy and patient reach is not clinical outcome.',example:'A retail supplement estimate and hospital medical-nutrition estimate can overlap or use different channels and should remain separate.',vietnam:'State category, jurisdiction, channel, period, currency and recognized-revenue basis before comparison.'},
'How Are Product-Specific Evidence and Claims Planned?':{dimensions:['Ingredient evidence','Finished-product evidence','Population','Serving or dose','Outcome','Claim substantiation','Uncertainty'],scope:'Evidence must match the ingredient or finished formulation, intended use, population, amount, comparator and outcome. Observed association is not automatically causation.',insight:'Clinical evidence is not a marketing claim, and one study cannot be generalized to all consumers, formulations or health outcomes.',example:'An ingredient study in one population may support research rationale but not a broad disease-treatment claim for every finished product.',vietnam:'Use current claim and advertising rules; flag unsupported high-stakes claims as Verification Required — Do Not Publish.'},
'How Do Quality Systems, Testing and Batch Release Work?':{dimensions:['Specification','Hygiene','Process control','Batch record','Laboratory test','Deviation','Release','Corrective action'],scope:'Quality systems prevent and detect contamination, mix-ups, variability and documentation failures through controlled materials, processes, tests, records and release decisions.',insight:'Manufacturing quality supports consistency and safety but does not itself demonstrate clinical effectiveness.',example:'A conforming batch meets approved specifications and release criteria; that result does not prove benefit for every user.',vietnam:'Apply category-specific manufacturing and testing requirements rather than one universal standard.'},
'How Do Healthcare Product Businesses Generate Revenue?':{dimensions:['Product sale','Wholesale','Retail','E-commerce','Institutional channel','Contract manufacturing','Repeat purchase','Recognized revenue'],scope:'Revenue can arise from branded products, wholesale, retail, direct channels, specialist or institutional sales and contract manufacturing. Sales, cash, contribution, repeat purchase and health outcome remain separate.',insight:'HYPOTHETICAL — A product sold for USD30 with USD6 ingredients, USD4 manufacturing, USD2 QA, USD2 packaging and USD3 distribution expense has USD17 defined cost and USD13 contribution, or 43.3%.',example:'HYPOTHETICAL calculation: cost=6+4+2+2+3=USD17; contribution=30−17=USD13; margin=13/30=43.3%.',vietnam:'Do not present hypothetical values as company or market figures; define channel, tax, returns and cost scope.'},
'What Determines Product, Quality and Commercial Costs?':{dimensions:['Ingredient','Formulation and R&D','Manufacturing','Testing and QA','Packaging','Regulatory documentation','Distribution','Brand activity','Expiry and return','Working capital'],scope:'Cost includes ingredients, formulation, manufacturing, testing, quality, packaging, documentation, logistics, channel terms, responsible communication, returns, expiry and finance.',insight:'HYPOTHETICAL — With USD14 COGS, DTC at USD30 less USD5 fulfillment and USD4 acquisition contributes USD7; pharmacy revenue USD22 less USD2 channel cost contributes USD6; distributor revenue USD18 less USD1 logistics contributes USD3.',example:'HYPOTHETICAL margins: DTC 7/30=23.3%; pharmacy 6/22=27.3%; distributor 3/18=16.7%. Scope and customer-acquisition treatment must be aligned.',vietnam:'Channel profitability does not establish efficacy, safety or consumer suitability.'},
'Which KPIs Drive Healthcare Product Profitability?':{dimensions:['Revenue per SKU','COGS','ASP','Gross margin','Contribution margin','Distribution margin','Inventory turnover','DIO','Expiry loss','Stock-out rate','Return rate','CAC','Repeat purchase','Portfolio mix'],scope:'Commercial KPIs need aligned SKU, channel, period and accounting definitions. DIO relates inventory to COGS under a stated method; expiry loss uses cost or another explicit basis; repeat purchase is not evidence of efficacy.',insight:'HYPOTHETICAL — 10,000 units at USD12 cost create USD120,000 inventory. If 8% expire, 800 units create a USD9,600 write-off before disposal or recovery effects.',example:'HYPOTHETICAL calculation: expired units=10,000×8%=800; write-off=800×12=USD9,600. Slower turnover and long replenishment can increase expiry and stock-out tradeoffs.',vietnam:'Keep commercial performance separate from safety, clinical evidence and lawful claims.'},
'How Do Product Classification, Labeling and Claims Rules Evolve?':{dimensions:['Classification','Market-access process','Label','Nutrient content claim','Health claim','Disease claim','Advertising','Jurisdiction'],scope:'Classification, notification or registration, labeling, claims and advertising requirements depend on product, ingredient, intended use, target user, channel and current jurisdiction.',insight:'A foreign authorization does not automatically apply in Vietnam, and legal market access is not independent clinical validation.',example:'A product reformulation or claim change can alter documentation, labeling, evidence and market-access obligations.',vietnam:'Verify current official texts; do not invent article numbers, permitted claims, certification duties or effective dates.'},
'How Do Healthcare Products and Nutrition Companies Make Money?':{dimensions:['Product sales','Licensing','Manufacturing contract','Wholesale margin','Service fee','Regulatory responsibility'],intro:'This chapter explains the main ways healthcare products and nutrition companies earn revenue and what each way makes them accountable for.',scope:'Companies earn revenue in different ways depending on their role. Brand owners sell their own products through retail, pharmacy, direct and institutional channels. Manufacturers earn from contract production for other companies’ brands. Distributors and wholesalers earn a margin for holding stock and providing market access. Other models earn from licensing or service fees. Revenue is not profit or cash, and each model carries its own responsibility for quality, claims and compliance: a brand owner stays responsible for its product even when others make or distribute it.',insight:'The way a company earns revenue defines what it is accountable for. Selling a product, manufacturing for another brand, distributing or licensing each create different obligations for quality, claims and regulation, so revenue models cannot be compared without comparing responsibility.',example:'One company sells its own supplement under its brand, another makes products for brand owners under contract, and a third imports and distributes them. All three earn revenue from the same product, but the first carries the main responsibility for the brand’s claims and evidence, the second for manufacturing quality to agreed specifications, and the third for storage, traceability and what it tells customers.',vietnam:'Check the current Vietnamese rules for the product’s category and for each party’s activity, whether manufacture, import, distribution or sale, because licensing, labeling, advertising and quality duties differ by product class and role. Do not present revenue, contribution or margin figures from other contexts as Vietnamese benchmarks.',sources:['whoReg','whoGmp','vnPharmacy','vnFoodLaw','vnConsumer'],definitions:{'Product sales':'Revenue from selling a company’s own branded products to consumers or channel partners.','Licensing':'Revenue from allowing another party to use a brand, formulation or other rights under agreed terms.','Manufacturing contract':'An agreement under which a manufacturer produces for another company, earning revenue from the production service while the customer owns the brand.','Wholesale margin':'The difference between what a distributor or wholesaler pays for a product and what it charges its customers, earned for holding stock and providing access.','Service fee':'Revenue from a defined service, such as testing, regulatory documentation or distribution services, rather than from selling a product.'}},
'How Do Importer, Distributor, Private-Label and Integrated Models Compare?':{dimensions:['Importer','Distributor','Private-label model','Integrated model','Quality agreement','Legal responsibility'],intro:'This chapter compares four operating models that split the same value chain between a company and its partners.',scope:'Four operating models split the value chain differently. An importer brings a product into a market and handles import documentation. A distributor buys, stores and resells to downstream sellers and often supplies market information. A private-label model sells under the company’s own brand a product that another company makes to its specification, which needs a quality agreement. An integrated model keeps development, production and brand in-house for control, at the cost of capital and capability. The choice follows product class, technical complexity, control needs, capital, market timing and current legal responsibility.',insight:'No operating model removes responsibility; it only moves where work is done. The right model depends on which capabilities and controls the company must hold itself, and each needs a clear allocation of legal responsibility for quality, traceability and communication.',example:'A foreign brand wants Vietnamese customers. It can sell through an importer or distributor that handles access and stock, commission a local manufacturer to make a private-label version under a quality agreement, or build its own capacity. The faster routes lean on partners but still require the brand to specify, oversee and answer for the product.',vietnam:'Contracts should define product custody, storage, traceability, forecasts, expiry, returns, claims, reporting, audits, recalls and who holds each legal responsibility under the rules for the product’s category. Verify current Vietnamese requirements for importing and distributing each product class; do not assume one model suits supplements, medicines and foods alike.',sources:['whoTrace','whoGmp','vnPharmacy','vnFoodLaw','vnDecree15','vnConsumer'],definitions:{'Importer':'A party that brings products into a market and handles import documentation; its legal responsibilities depend on the product category and local rules.','Distributor':'A party that buys, stores and resells products to downstream sellers, managing inventory, logistics and customer relationships.','Private-label model':'A model in which a company sells under its own brand a product that another company manufactures to the brand owner’s specifications.','Integrated model':'A model in which one company keeps several roles, such as development, manufacturing and brand, in-house, giving more control and requiring more capital.','Quality agreement':'A written agreement fixing specifications, testing, records, change control and corrective action between a brand owner and a manufacturer.'}},
'How Are Supplements and Consumer Health Products Segmented?':{dimensions:['Dietary supplement','Functional food','Fortified food','Consumer health product','Product segment','Intended use'],intro:'This chapter explains how supplements and consumer health products are grouped for commercial purposes and why segments never replace legal classification.',scope:'Segmentation groups products and customers for commercial purposes: by type (dietary supplements, functional foods, fortified foods and other consumer health products), by benefit area, by target user or life stage, by format and by channel. A segment is not a legal category. Classification depends on composition, intended use, claims and jurisdiction, and the Codex guideline for vitamin and mineral supplements applies to supplements regulated as foods and excludes foods for special dietary uses. A useful segmentation therefore sits on top of correct classification and never replaces it.',insight:'Segments describe how a market can be grouped; classification decides which rules apply. A product positioned in an attractive segment is not thereby permitted to make that segment’s claims, because classification, evidence and permitted channels still govern.',example:'A company groups its products into bone-health and child-nutrition segments. Inside one segment, a vitamin supplement, a fortified food and a specialized nutrition product can differ in classification, evidence needed, labeling and permitted sales channels, so the commercial segment cannot set the rules.',vietnam:'Classify each product under current Vietnamese rules before assigning it to a segment, using composition, intended use, claims and target user, and verify the relevant parts of the Food Safety Law, Decree No. 15/2018/ND-CP or the Law on Pharmacy as applicable. Do not apply another jurisdiction’s segment or claim category, such as a U.S. claim category, as Vietnamese law.',sources:['codexSupp','fdaClaims','vnFoodLaw','vnDecree15','vnPharmacy'],definitions:{'Dietary supplement':'A concentrated source of nutrients or other substances intended to supplement the diet; Codex guidelines treat vitamin and mineral supplements as foods, and a dietary supplement is not a medicine.','Functional food':'A food presented as offering a health-related benefit beyond basic nutrition; it remains a food and its claims must be supported under the rules that apply.','Fortified food':'A food to which nutrients have been added; its category and permitted statements depend on the rules of the jurisdiction.','Consumer health product':'A non-prescription health-related product sold directly to consumers; whether it is a medicine, a food or another class depends on its composition, intended use and claims.','Product segment':'A commercially useful group of products or customers, such as by benefit area or life stage; a segment does not change a product’s legal classification.'}},
'How Do General, Specialized and Medical Nutrition Differ?':{dimensions:['General nutrition','Specialized nutrition','Medical nutrition','Intended use','Professional supervision','Target population'],intro:'This chapter compares general, specialized and medical nutrition by intended use, user and the controls each brings.',scope:'General, specialized and medical nutrition differ mainly in intended use and in who they are for. General nutrition serves the general population as a supplement to ordinary diets. Specialized nutrition is designed for a defined group or need, and some rules treat foods for special dietary uses separately; for example, the Codex guideline for vitamin and mineral supplements excludes them. Medical nutrition is intended for the dietary management of defined medical needs under the applicable classification and use conditions. Each step toward medical use brings stricter evidence, labeling and use conditions, and sometimes professional supervision, depending on the jurisdiction.',insight:'General nutrition is not medical nutrition, and a product’s intended use, not its ingredients alone, places it. Moving from general to specialized to medical use raises the evidence and control expected, and a product cannot borrow the claims or channels of a more medical class.',example:'A product with similar nutrients can be offered as an everyday supplement, as a specialized product for a defined life stage, or as medical nutrition for a diagnosed need. Label, evidence, use instructions and permitted channel differ in each case, so the company must decide intended use first.',vietnam:'Determine the product’s intended use, target user and claims, and classify it under current Vietnamese rules before choosing positioning and channels. Verify category-specific requirements in the Food Safety Law, Decree No. 15/2018/ND-CP and any applicable pharmacy rules; do not assume that a foreign category such as medical nutrition carries the same requirements in Vietnam.',sources:['codexSupp','vnFoodLaw','vnDecree15','vnPharmacy'],definitions:{'General nutrition':'Products for the general population that contribute to ordinary diets, such as a vitamin or mineral supplement regulated as a food; claims stay within what the rules allow for foods.','Specialized nutrition':'Products made for a defined group or need, such as a life stage or dietary requirement; some rules treat foods for special dietary uses separately from general supplements.','Medical nutrition':'Nutrition products intended for dietary management of defined medical needs under the applicable classification and use conditions.','Intended use':'The purpose for which a product is designed and represented; it separates general, specialized and medical nutrition and can affect classification and requirements.','Professional supervision':'Involvement of a health professional in selecting or monitoring a product’s use; some products are used under it and tighter controls can apply.'}},
'How Do Formulation, Evidence, Classification and Positioning Interact?':{dimensions:['Formulation','Product-specific evidence','Product classification','Positioning','Claim substantiation','Serving or dose'],intro:'This chapter shows why formulation, evidence, classification and positioning must be decided together rather than one after another.',scope:'Formulation, evidence, classification and positioning are decided together. The formulation, meaning ingredients, amounts and form, affects which classification is possible. Classification, together with the rules of the jurisdiction, sets what claims can be made and what evidence is expected. The evidence must concern the finished product, its dose or serving, intended population and outcome; evidence about one ingredient alone does not automatically substantiate the product. Positioning, the benefit and user a product is presented to, must stay inside the classification and the evidence. A change to any one can force a review of the others.',insight:'Positioning cannot run ahead of evidence and classification. A claim is only as strong as the evidence for the finished product, and a change in formulation or claim changes what the product must be shown to be.',example:'A company reformulates a supplement with a higher amount of an ingredient and wants a stronger benefit claim. The change can affect classification and labeling, and earlier evidence on the old formulation, or on the ingredient alone, may not support the new statement. Evidence and documentation must be reviewed before the claim is used.',vietnam:'Review classification, labeling, advertising and claim rules from primary Vietnamese sources before finalizing positioning; the FDA claims guide illustrates substantiation but is a U.S. framework, not Vietnamese law. Flag unsupported high-stakes claims as Verification Required — Do Not Publish.',sources:['fdaClaims','codexSupp','vnFoodLaw','vnDecree15','vnPharmacy'],definitions:{'Formulation':'The ingredients, amounts and form of a finished product; changing it can change classification, evidence needs and labeling.','Product-specific evidence':'Evidence generated for the finished formulation, population, use, dose or serving and outcome in question.','Product classification':'The legal category assigned under applicable rules based on intended use, composition, claims and other factors.','Positioning':'How a product is presented to its target user, including its benefit, intended use and claims; positioning must stay within the product’s classification and supported evidence.','Claim substantiation':'Evidence appropriate to support a specific product statement under the rules that apply to it.'}},
'Who Purchases Healthcare and Nutrition Products?':{dimensions:['Consumer buyer','Family or caregiver buyer','Trade buyer','Professional recommendation','Institutional buyer','Purchaser versus user'],intro:'This chapter identifies who buys healthcare and nutrition products and why the buyer is not always the user.',scope:'Several kinds of buyer purchase these products, and the buyer is not always the user. Consumers buy for themselves, and parents and carers buy for family members. Pharmacies, retailers and distributors buy to resell, so their orders are shipments into a channel rather than use. Health professionals often influence purchases without making them. Institutions such as hospitals and clinics buy for their own patients under their own procurement rules. Each buyer type has different information needs, regulatory touchpoints and ways of being reached.',insight:'Knowing who buys is not the same as knowing who uses or benefits. A channel partner’s purchase shows demand from the trade, not that a user needed or continued the product, so the buyer, the user and the influencer must be identified separately.',example:'A distributor orders stock, a pharmacy buys from the distributor, and a parent buys from the pharmacy for a child on a pharmacist’s advice. That is three purchases, one recommender and one user, each visible in different data and subject to different obligations.',vietnam:'Check which buyers may lawfully buy, sell or be advertised to for each product category in Vietnam, for example whether a product may be sold through pharmacies, retail or online, and which consumer-protection and personal-data duties arise under the Law on Protection of Consumer Rights (No. 19/2023/QH15) and Law No. 91/2025/QH15.',sources:['whoTrace','vnPharmacy','vnFoodLaw','vnConsumer','vnData'],definitions:{'Consumer buyer':'An individual who buys a product for their own use, usually through retail, pharmacy or online channels.','Family or caregiver buyer':'A person who buys for someone else, such as a parent or carer, so the buyer and the user differ.','Trade buyer':'A pharmacy, retailer or distributor that buys products to resell; its purchases are shipments into the channel, not use by a consumer.','Professional recommendation':'Advice from a health professional that influences what is bought even when the professional does not make the purchase.','Institutional buyer':'An organization, such as a hospital or clinic, that purchases products for its own patients or programs under its own procurement rules.'}},
'How Do Consumer, Family, Life-Stage and Specialized Needs Differ?':{dimensions:['Consumer need','Family need','Life stage','Specialized need','Target population'],intro:'This chapter explains how needs differ by who the user is and why evidence, formulation and claims must be matched to each population.',scope:'Needs differ by who the user is and why they use the product. Consumers buy to meet their own health or nutrition goals. Families buy for others, so the buyer’s concerns and the user’s needs can diverge. Life-stage needs follow changes across life, and specialized needs arise from defined dietary or medical requirements. These differences matter because the evidence, formulation, labeling and communication that suit one population do not automatically suit another, and a product’s intended use and classification must match the need it addresses.',insight:'A need defines a target population, and evidence is valid only for the population it was gathered on. Meeting different needs means matching formulation, claims and channel to each, not stretching one product’s story across all of them.',example:'A product developed for general adult wellness is marketed to parents for a child. The need, the user and the relevant evidence are now different: evidence for adults does not substantiate use for a child, and the product’s classification, labeling and claims must be reviewed for the new population.',vietnam:'Define the target user and need for each product, and verify the Vietnamese classification, labeling and advertising rules that apply before positioning it to families or specific life stages. Avoid health or disease claims that cannot be substantiated under current Vietnamese rules.',sources:['fdaClaims','codexSupp','vnFoodLaw','vnDecree15','vnConsumer'],definitions:{'Consumer need':'A health or nutrition goal an individual wants to meet for themselves, such as maintaining general wellness; it is not in itself a medical need.','Family need':'A need met by buying for others in a household, so the buyer’s priorities, such as trust and ease of use, can differ from the user’s.','Life stage':'A period of life, such as infancy, childhood, adulthood or older age, whose nutritional circumstances differ and whose products may call for more careful evidence and communication.','Specialized need':'A defined dietary or health-related requirement of a particular group, which may be served by specialized or medical nutrition under their classification and use conditions.','Target population':'The group of users a product and its evidence are intended for; evidence for one population does not automatically apply to another.'}},
'How Do Retail, Pharmacy, Professional and Institutional Buyers Differ?':{dimensions:['Retail buyer','Pharmacy buyer','Professional channel','Institutional buyer','Traceability','Product custody'],intro:'This chapter compares what retail, pharmacy, professional and institutional buyers need from a supplier and what contracts with them must cover.',scope:'Retail, pharmacy, professional and institutional buyers differ in what they need from a supplier. Retail buyers focus on assortment, price, authenticity and customer experience. Pharmacies add professional guidance and are limited to the products permitted in that channel. Professional channels depend on health professionals’ recommendation or supply. Institutional buyers purchase under their own procurement rules and need documentation, reliable supply and traceability. Because buyers hold, resell or recommend products before anyone uses them, contracts should define custody, storage, traceability, expiry, returns, claims, reporting, audits, recalls and downstream seller controls.',insight:'Each buyer type creates different requirements for information, quality documentation and accountability. A supplier that treats all buyers alike either over-controls low-risk channels or under-controls those where professional guidance, traceability or institutional procurement rules apply.',example:'The same supplement may be listed by an online marketplace, stocked by a pharmacy with a pharmacist’s advice, and recommended by a clinic. The marketplace needs listing and authenticity controls, the pharmacy needs product information to guide customers, and the clinic needs documentation and reliable supply. Each channel’s contract should state its own duties.',vietnam:'Verify which categories of product may be sold or advertised through each channel in Vietnam, and write recall, traceability, storage, claims and reporting duties into contracts with each buyer. Consumer-protection duties (Law No. 19/2023/QH15) and personal-data duties (Law No. 91/2025/QH15) can apply to channel operations.',sources:['whoTrace','vnPharmacy','vnFoodLaw','vnConsumer','vnData'],definitions:{'Retail buyer':'A retailer or marketplace that buys or lists products for sale to consumers; its priorities include assortment, price and customer experience.','Pharmacy buyer':'A pharmacy that buys products for sale with professional guidance where permitted; which products it may sell depends on their legal category.','Professional channel':'A channel in which a health professional recommends or supplies a product as part of care or advice.','Institutional buyer':'A hospital, clinic or similar organization that purchases under its own procurement requirements and typically needs documentation, supply reliability and traceability.','Traceability':'The ability to identify and follow a product, batch, supplier or transaction through defined supply-chain stages.'}},
'How Do E-Commerce and Direct-to-Consumer Channels Differ?':{dimensions:['E-commerce marketplace','Direct-to-consumer','Customer data','Fulfillment','Customer acquisition','Returns and expiry'],intro:'This chapter compares marketplace and direct online selling by who owns the customer, who bears cost and which duties apply.',scope:'E-commerce and direct-to-consumer channels both sell online but differ in who owns the customer. On a marketplace, the platform provides traffic, listing rules and often fulfillment, and the seller gives up some control over data, pricing and presentation. In a direct channel, the company sells through its own website, app or subscription and so owns the customer relationship and its data, but also bears acquisition, fulfillment, returns and customer service. Online sales also require authentic goods, accurate and lawful product communication, and careful handling of personal data.',insight:'Online and direct channels should be judged on contribution and inventory, not on order volume. A digital discount can raise sales while lowering contribution or tying up working capital, and owning the customer brings data-protection and consumer-protection duties along with control.',example:'A supplier discounts a supplement on its own site and wins more orders. After deducting the discount, fulfillment, returns, expired stock and acquisition cost, the contribution per order has fallen. The same product on a marketplace may sell fewer units but leave a different margin after platform terms.',vietnam:'Verify which products may be sold or advertised online in Vietnam and under what conditions, and apply the Law on Protection of Consumer Rights (No. 19/2023/QH15, effective 1 July 2024) and the Law on Personal Data Protection (No. 91/2025/QH15, effective 1 January 2026) to listings, returns and customer data. Duties depend on the product, transaction and current implementing rules.',sources:['vnConsumer','vnData','vnFoodLaw','vnPharmacy','vnDecree15'],definitions:{'E-commerce marketplace':'An online platform on which sellers list products to its customers; the platform provides reach and sets listing rules, while product, claims and authenticity duties remain with the seller.','Direct-to-consumer':'A model in which a company sells to consumers through its own channels, such as a website or subscription, and so owns the customer relationship, fulfillment and data.','Customer data':'Personal information about buyers collected by the seller or platform; collecting and using it carries personal-data protection duties.','Fulfillment':'Storing, packing, delivering and handling returns of orders, which in direct channels is a cost the seller bears or passes on.','Customer acquisition':'The activity and cost of attracting a new buyer, such as advertising and discounts; whether it pays off depends on the contribution that buyer later generates.'}},
'Who Participates in the Healthcare Products Ecosystem?':{dimensions:['Brand owner','Manufacturer','Ingredient supplier','Distributor and retailer','Health professional','Regulator','Laboratory','Consumer'],intro:'This chapter maps the parties that create, make, move, regulate, check and use healthcare and nutrition products.',scope:'The ecosystem includes the parties that create, make, move, regulate, check and use products. Brand owners position and sell products and remain responsible for them. Manufacturers and ingredient suppliers produce and provide materials under specifications and quality controls. Distributors and retailers provide access and logistics, and health professionals advise users. Regulators decide classification and market-access rules, laboratories test quality, and consumers and communities choose, use and report experience. A single company may combine several roles, as in an integrated model.',insight:'A healthcare product is the result of many parties, so responsibility for quality, evidence and safe use is shared and must be allocated explicitly. Mapping who does what exposes gaps in oversight that a single-company view hides.',example:'A supplement involves a brand owner, an ingredient supplier, a contract manufacturer, a testing laboratory, a distributor, a pharmacy and a regulator who sets the rules for its category. When a complaint arrives, each party may hold part of the information needed to respond.',vietnam:'Identify each participant’s legal role for the product’s category under current Vietnamese rules, covering manufacture, import, distribution, sale, advertising and safety reporting, before assigning responsibility in contracts. Participants and requirements differ among medicines, foods and supplements.',sources:['whoReg','whoGmp','whoPv','whoTrace','vnPharmacy','vnFoodLaw'],definitions:{'Brand owner':'The company that positions and sells a product under its name and remains responsible for its specifications, evidence and compliant communication.','Manufacturer':'The company that makes a product, for itself or for others, under specifications, quality controls and records.','Ingredient supplier':'A company that supplies materials used in formulations; the buyer must qualify the supplier and control the materials.','Distributor and retailer':'Companies that move, store and sell products to users, providing access, logistics and sometimes professional guidance.','Health professional':'A clinician, pharmacist or other professional who advises users and can influence which products are chosen and how they are used.'}},
'How Do Researchers, Manufacturers, Channels and Professionals Collaborate?':{dimensions:['Evidence and research','Quality agreement','Traceability','Professional guidance','Post-market monitoring','Complaint handling'],intro:'This chapter explains the hand-offs and information flows that let researchers, manufacturers, channels and professionals work as one system.',scope:'Collaboration works through defined hand-offs. Researchers establish what a product can credibly do. Manufacturers turn the formulation into consistent product under specifications and a quality agreement. Channels make it available while keeping it traceable. Professionals help the right user choose and use it appropriately. Information must also flow back: complaints, safety signals and use information collected after launch reach the brand owner, the manufacturer and, where required, regulators. WHO guidance treats traceability as a complement to regulation, surveillance and response, not a substitute for them.',insight:'Collaboration is only as strong as its information flows. Specifications, quality agreements, traceability and feedback let each party act on what the others know; where those links are missing, a quality or safety problem can travel unnoticed from one party to the next.',example:'A complaint about a product reaches a pharmacy. If the pharmacy can identify the batch and report it to the distributor and brand owner, and the manufacturer can trace its production records, the problem can be assessed and acted on. Without batch traceability, each party sees only part of the picture.',vietnam:'Write quality, traceability, complaint, safety-reporting and recall duties into agreements between participants, using the current Vietnamese rules for the product’s category to decide what must be reported and to whom. Not every food or supplement follows the same safety-reporting system as medicines and vaccines.',sources:['whoPv','whoTrace','whoGmp','vnPharmacy','vnFoodLaw','vnDecree15'],definitions:{'Evidence and research':'The scientific work that shows what an ingredient or product can credibly do and for whom; it informs formulation and what may be claimed.','Quality agreement':'A written agreement between a brand owner and a manufacturer fixing specifications, testing, records, change control and corrective action.','Traceability':'The ability to identify and follow a product, batch, supplier or transaction through defined supply-chain stages; WHO treats it as a complement to regulation and surveillance, not a replacement.','Professional guidance':'Advice from health professionals that helps the right user choose and use a product appropriately.','Post-market monitoring':'Collection and evaluation of quality, complaint, safety and use information after commercialization.'}},
'How Do Regulators, Laboratories, Consumers and Communities Shape Value?':{dimensions:['Regulator','Laboratory','Consumer','Community trust','Market access'],intro:'This chapter explains how regulators, laboratories, consumers and communities decide whether a product is allowed, shown to be what it claims, chosen and trusted.',scope:'Four outside forces shape what a product is worth. Regulators decide classification, market access and rules on quality, labeling and advertising, so they set the conditions under which value can be captured at all. Laboratories test materials and products, which supports batch release, investigations and quality claims. Consumers decide whether to buy, continue and recommend, and consumer-protection law protects them. Communities carry trust or doubt between users, families and professionals. Value is created where quality, evidence and access come together with trust, and can be lost quickly where any of them fails.',insight:'Value and trust are conferred as well as created. Regulators, laboratories, consumers and communities decide whether a product is allowed, shown to be what it claims, chosen and trusted, so a company cannot capture durable value without meeting each of them.',example:'A product with a distinctive formulation can still lose value if a laboratory result contradicts its label, a regulator questions its classification or users in a community report problems. Each independent signal can override the brand’s own claims.',vietnam:'Treat regulators, laboratory testing and consumer-protection rules as part of a product’s cost and credibility, not as hurdles to manage afterwards. Verify the current Vietnamese rules and authorities for the product category from primary sources, and keep records that show claims, quality and complaints were handled.',sources:['whoReg','whoGmp','vnPharmacy','vnFoodLaw','vnConsumer'],definitions:{'Regulator':'A public authority that sets or enforces the rules for a product category, including classification, market access, quality, labeling and advertising.','Laboratory':'A facility that tests materials or products against specifications; its results support batch release, investigations and statements about quality.','Consumer':'A user and buyer who chooses, pays for and reports experience with a product, and whose protection is a legal and commercial concern.','Community trust':'The confidence or doubt that spreads among users, families and professionals through shared experience and information, affecting whether a product is adopted.','Market access':'The regulatory, evidence, payment, procurement and channel conditions enabling appropriate product availability.'}},
'How Do Pharmacy, Retail, Distributor and Institutional Channels Work?':{dimensions:['Pharmacy channel','Retail channel','Distributor','Institutional channel','Channel terms','Working capital'],intro:'This chapter explains how pharmacy, retail, distributor and institutional channels reach customers and what each leaves the supplier after terms and costs.',scope:'Each channel reaches customers in a different way and carries different economics. Pharmacies provide professional guidance for products that may lawfully be sold there. Retail channels add reach and convenience through physical and online outlets. Distributors buy, hold and resell, earning a wholesale margin for inventory, logistics and market access. Institutional channels sell to organizations that buy under their own procurement rules. In every channel, channel terms such as price, margin, returns, payment and reporting decide how much of a sale the supplier keeps, and inventory, expiry and working capital shift cost between the supplier and its partner.',insight:'Channel choice changes both reach and contribution. Net sales through a channel should be reconciled with that channel’s terms, returns, expiry and working capital, because the channel with the highest sales is not necessarily the one that adds the most contribution.',example:'A supplier sells through a distributor, a pharmacy chain and a hospital contract. Each pays differently, returns or expires stock differently and requires different documentation, so comparing them on headline sales alone hides what each leaves after terms, returns and tied-up stock.',vietnam:'Confirm which channels may sell each product category in Vietnam and what storage, traceability, advertising and complaint duties apply to each, using the Law on Pharmacy, the food-safety rules and the consumer-protection law. Measure channel economics by product, customer group and channel on a consistent basis.',sources:['whoTrace','vnPharmacy','vnFoodLaw','vnConsumer'],definitions:{'Pharmacy channel':'Sales through pharmacies, where professional guidance and the legal category of each product determine what can be sold and how.','Retail channel':'Sales through physical or online retailers, which provide reach and convenience in exchange for margin, listing terms and sometimes returns arrangements.','Distributor':'A wholesale intermediary that buys, stores and resells to downstream sellers, earning a margin for inventory, logistics and access.','Institutional channel':'Sales to organizations such as hospitals or clinics under their own procurement rules, which often need documentation, supply reliability and traceability.','Channel terms':'The commercial conditions agreed with a channel partner, such as price, margin, returns, payment and reporting, that determine what the supplier keeps from each sale.'}}}
;

const unique=<T,>(items:T[],key:(item:T)=>string)=>Array.from(new Map(items.map(item=>[key(item),item])).values());
function healthcareLegacyTargets(module:number,lesson:string,sourceCount:number,targetCount:number){const explicit=HEALTHCARE_LEGACY_TARGETS[`${module}:${lesson}`];if(explicit&&explicit.length===sourceCount)return explicit;return Array.from({length:sourceCount},(_,i)=>Math.round(i*(targetCount-1)/Math.max(1,sourceCount-1)))}
export function standardizeHealthcareProductLessons(module:number,lessons:HealthcareProductLesson[]):HealthcareProductLesson[]{return lessons.map(([lesson,items])=>{const titles=HEALTHCARE_CANONICAL_TITLES[module]?.[lesson]??items.map(item=>item.title);const groups=titles.map(()=>[]as number[]);const targets=healthcareLegacyTargets(module,lesson,items.length,titles.length);targets.forEach((target,legacyIndex)=>groups[Math.max(0,Math.min(titles.length-1,target))].push(legacyIndex));const sourceForTarget=titles.map((_,targetIndex)=>{let best=0;let distance=Infinity;targets.forEach((target,sourceIndex)=>{const nextDistance=Math.abs(target-targetIndex);if(nextDistance<distance){distance=nextDistance;best=sourceIndex}});return best});const next=titles.map((title,index)=>{const legacyIndexes=groups[index];const sourceIndex=sourceForTarget[index];const base=items[sourceIndex];const siblings=sourceForTarget.map((value,targetIndex)=>({value,targetIndex})).filter(row=>row.value===sourceIndex);const rank=Math.max(0,siblings.findIndex(row=>row.targetIndex===index));const sourceItems=legacyIndexes.length?legacyIndexes.map(i=>items[i]):[base];const dimensions=legacyIndexes.length>1?Array.from(new Set(sourceItems.flatMap(item=>item.dimensions))):base.dimensions.filter((_,i)=>i%siblings.length===rank);const focusedDimensions=dimensions.length?dimensions:[base.dimensions[rank%base.dimensions.length]];const detail=HEALTHCARE_DETAILS[title];return{title,dimensions:detail?.dimensions??focusedDimensions,insight:detail?.insight??`${base.insight} This chapter focuses specifically on ${focusedDimensions.join(', ')}.`,scope:detail?.scope??`${title} examines ${focusedDimensions.join(', ')}. ${base.scope}`,example:detail?.example??sourceItems.map(item=>item.example).join(' '),vietnam:detail?.vietnam??sourceItems.map(item=>item.vietnam).join(' '),sources:detail?.sources??unique(sourceItems.flatMap(item=>item.sources),id=>id),intro:detail?.intro,definitions:detail?.definitions,stats:sourceItems.flatMap(item=>item.stats??[]),legacyIndex:legacyIndexes[0],legacyIndexes,legacyCompletionIndex:legacyIndexes[0]}});return[lesson,next]})}
export function buildHealthcareProductLegacyManifest(module:number,lessons:HealthcareProductLesson[]){const standardized=standardizeHealthcareProductLessons(module,lessons);return standardized.flatMap(([lesson,items],lessonIndex)=>items.flatMap((item,successorIndex)=>(item.legacyIndexes??[]).map(legacyIndex=>({module,lesson,lessonIndex,legacyIndex,legacyTitle:lessons[lessonIndex][1][legacyIndex]?.title??'',legacyObjective:`Explain ${lessons[lessonIndex][1][legacyIndex]?.title.toLowerCase()??'the original chapter'}.`,successorIndex,successorTitle:item.title,sources:lessons[lessonIndex][1][legacyIndex]?.sources??[],migrationVersion:'healthcare-products-full-v1'}))))}

const definitions:Record<string,string>={'Intended use':'The purpose for which a product is designed, represented and used; it can affect classification and requirements.','Product classification':'The legal category assigned under applicable rules based on intended use, composition, claims and other factors.','Claim substantiation':'Evidence appropriate to support a specific product statement under the rules that apply to it.','Ingredient evidence':'Research concerning an ingredient; it does not automatically establish a finished product’s effect.','Product-specific evidence':'Evidence generated for the finished formulation, population, use, dose or serving and outcome in question.','Medical nutrition':'Nutrition products intended for dietary management of defined medical needs under the applicable classification and use conditions.','Pharmacovigilance':'Detection, assessment, understanding and prevention of adverse effects or other medicine- or vaccine-related problems.','Traceability':'Ability to identify and follow a product, batch, supplier or transaction through defined supply-chain stages.','Batch release':'Documented authorization that a produced batch meets applicable specifications before distribution.','Change control':'Governed assessment, approval, implementation and documentation of a proposed change.','Sell-through':'Sales from a channel partner to its customer, distinct from shipments into the channel.','Contribution margin':'Revenue less defined variable or controllable costs; scope must be stated.','Adherence':'Extent to which use follows an agreed or recommended regimen under a defined measure.','Post-market monitoring':'Collection and evaluation of quality, complaint, safety and use information after commercialization.','Health literacy':'Ability to access, understand, assess and use health information and services.','Market access':'The regulatory, evidence, payment, procurement and channel conditions enabling appropriate product availability.','Nutrient content claim':'Statement about the presence, absence or level of a nutrient under applicable rules.','Health claim':'Statement relating a product or constituent to health under the applicable evidence and legal framework.','Disease-treatment claim':'Claim to diagnose, treat, cure or prevent disease; classification and permissibility are jurisdiction-specific.','COGS':'Cost of goods sold under the stated accounting scope.','Days Inventory Outstanding':'Average inventory divided by COGS and multiplied by days in the period under an aligned basis.','Expiry loss':'Inventory cost or another stated value written off because products expire before sale or use.','Repeat purchase rate':'Repeat purchasers or repeat transactions divided by an explicitly defined eligible customer or transaction population.'};const terms=(a:string[],own?:Record<string,string>)=>a.slice(0,5).map(term=>({term,definition:own?.[term]??definitions[term]??`A core Healthcare Products and Nutrition concept related to ${term.toLowerCase()}.`}));function chapter(module:number,lesson:string,item:HealthcareProductItem,index:number):HealthcareProductCardData{const impact=`For decision-makers, ${item.insight.toLowerCase()} Define product category, intended use, claim, target user, evidence, channel, jurisdiction, safety responsibility and economics before acting.`;const recap=[item.insight,impact,`Key dimensions include ${item.dimensions.join(', ')}.`];const visualKind=`healthcare-products-m${module}-${index}`as HealthcareProductVisualKind;return{title:`${String(index).padStart(2,'0')} ${item.title}`,chapterTitle:lesson,readingTime:'8',legacyIndex:item.legacyIndex,legacyIndexes:item.legacyIndexes,legacyCompletionIndex:item.legacyCompletionIndex,migrationVersion:'healthcare-products-full-v1',objective:`Explain ${item.title.toLowerCase()} and apply it to an evidence-led healthcare or nutrition decision.`,mateIntro:item.intro??`This chapter examines ${item.scope}`,keyInsight:item.insight,concepts:[],narrative:[{label:'What it is',text:item.scope},{label:'Why it is happening',text:`Changing health needs, scientific progress, regulation, digital access, affordability pressure and demand for trustworthy information make this topic strategically important. ${item.insight}`},{label:'Real-world example',text:item.example},{label:'Vietnam example',text:item.vietnam},{label:'Business impact',text:impact}],visualKind,visualHeading:HEALTHCARE_PRODUCTS_CHAPTER_VISUALS[visualKind]?.heading??item.title,visualIntro:HEALTHCARE_PRODUCTS_CHAPTER_VISUALS[visualKind]?.intro??'Use the visual to connect health need, classification, evidence, product, quality, access, appropriate use, monitoring and economics.',imageAlt:`Casemate Healthcare Products and Nutrition visual for ${item.title}`,statTiles:item.stats??[{value:String(item.dimensions.length),label:'Decision dimensions',description:item.dimensions.join(' · ')},{value:String(item.sources.length),label:'Evidence sources',description:'Official legal, intergovernmental, standards, or clearly scoped regulatory evidence.'},{value:'1',label:'Health-value test',description:'Define need, evidence, safety, access, outcome and sustainable economics before scaling.'}],statsNote:item.stats?'Figures retain product category, jurisdiction, population, period, denominator and result, target, estimate or guidance status.':'Tiles summarize the framework; registration, shipment, sell-through, patient reach, adherence, outcome, revenue, cash and profit are not interchangeable.',keyTerms:terms(item.dimensions,item.definitions),recap,chapterRecap:recap.join(' '),deepDiveTitle:'How evidence, quality and access turn a health need into responsible value—and where classification, claims or supply can fail',body:<F2DeepDive paragraphs={[item.scope,item.insight,item.example,item.vietnam,impact]} evidence="Separate product class, intended use, claim, ingredient evidence, finished-product evidence, approval, batch quality, channel, use, safety signal, outcome and economics."/>,sources:item.sources.map(id=>HEALTHCARE_PRODUCT_SOURCES[id])}}function seed(chapter:string,q:string,a:string,c:string){return{chapter,objective:q,question:q,application:a,correct:c,wrong:['Treat every health-related product as one regulatory and commercial category','Use ingredient-level or preliminary evidence as conclusive proof for every finished product and user','Scale claims or channels before verifying classification, quality, safety, data rights and economics']as[string,string,string],explanation:'Healthcare and nutrition decisions require a defined need, product class, intended use, evidence, quality system, channel, jurisdiction, safety responsibility and measurable outcome.'}}function calculationSeed(chapter:string,question:string,application:string,correct:string,wrong:[string,string,string]){return{chapter,objective:question,question,application,correct,wrong,explanation:'Use the stated product, channel, unit, revenue and cost assumptions only. Commercial performance does not prove product efficacy or safety.'}}
function quiz(prefix:string,topics:string[],chapterCount:number){if(prefix==='healthcare-products-m3-l4')return f2Quiz(prefix,[calculationSeed('1','A HYPOTHETICAL product sells for USD30 with USD17 defined cost. What are contribution and margin?','Subtract ingredients, manufacturing, QA, packaging and distribution expense.','USD13 and 43.3%',['USD17 and 56.7%','USD13 and 76.5%','USD30 and 100%']),calculationSeed('2','A HYPOTHETICAL DTC channel has USD30 revenue, USD14 COGS, USD5 fulfillment and USD4 acquisition cost. What is contribution?','Subtract the stated channel costs.','USD7, or 23.3%',['USD16','USD11','USD21']),calculationSeed('2','A pharmacy channel has USD22 recognized revenue, USD14 COGS and USD2 channel cost. What is contribution?','Use the pharmacy revenue basis.','USD6, or 27.3%',['USD8','USD20','USD4']),calculationSeed('3','10,000 units cost USD12 each and 8% expire. What is the HYPOTHETICAL write-off?','Calculate expired units and cost.','USD9,600',['USD960','USD12,000','USD120,000']),seed('3','Why must repeat purchase, product registration, safety and efficacy remain separate?','A product has high repeat sales. What does that prove?','Commercial behavior only, not independent clinical efficacy, universal suitability or legal claim permission')]);return f2Quiz(prefix,topics.slice(0,5).map((topic,i)=>seed(String(i%chapterCount+1),`What is central to ${topic}?`,`A team evaluates ${topic}. What should guide it?`,'Defined health need, product class, intended use, evidence, quality, access, safety and economics')))}export function buildHealthcareProductModule(module:number,lessons:HealthcareProductLesson[],topics:string[][],next:string[],theme:string){const standardized=standardizeHealthcareProductLessons(module,lessons);let visualIndex=0;const decks:Record<string,HealthcareProductCardData[]>={};const quizzes:Record<string,FashionM2Question[]>={};const takeaways:Record<string,FashionM2Takeaways>={};standardized.forEach(([lesson,items],i)=>{decks[lesson]=items.map(item=>chapter(module,lesson,item,++visualIndex));quizzes[lesson]=quiz(`healthcare-products-m${module}-l${i+1}`,topics[i],items.length);takeaways[lesson]={learned:`You can explain ${lesson.toLowerCase()} across Healthcare Products and Nutrition.`,keyTakeaways:[`Apply ${theme} to a defined product class, intended use, user, jurisdiction and channel.`,`Separate ingredient evidence, finished-product evidence, approval, shipments, sell-through, patient reach, adherence, outcomes, revenue and profit.`,`Quality, safety, appropriate claims, access, affordability, supply and trust jointly shape sustainable value.`,`Vietnam opportunities require current category-specific legal verification, credible evidence, reliable distribution and responsible communication.`,`Use sources with explicit product scope, population, jurisdiction, period, denominator and evidence status.`],businessImplications:'Build around a defined health or nutrition need, establish classification and evidence early, govern quality and claims, select appropriate channels, monitor safety and outcomes, and scale only when contribution and access are sustainable.',remember:'Health demand does not make every product suitable or every claim valid; classification, evidence, quality, appropriate use and trust determine durable value.',nextLesson:next[i]??''}});return{decks,quizzes,takeaways}}export function buildHealthcareProductVisuals(module:number,lessons:HealthcareProductLesson[]){const standardized=standardizeHealthcareProductLessons(module,lessons);const specs:Record<string,VisualSpec>={};let index=0;standardized.forEach(([,items])=>items.forEach(item=>{const key=`healthcare-products-m${module}-${++index}`;specs[key]=HEALTHCARE_PRODUCTS_CHAPTER_VISUALS[key]?.spec??{layout:'taxonomy',title:item.title,kicker:'',root:item.title,rootDetail:'Factors considered together, not in sequence',groups:Array.from(new Set(item.dimensions)).map(label=>({label})),takeaway:item.insight}}));return specs}export function renderHealthcareProductVisual(specs:Record<string,VisualSpec>,kind:HealthcareProductVisualKind){const spec=specs[kind];return spec?<VisualView spec={spec}/>:null}
